import {uid,today,money} from './domain.js';
import {invoiceTemplates,defaultInvoiceDesign} from './invoice-design.js';
import {calculateInvoice,prepareInvoice,createManualInvoice,saveInvoiceDefaults} from './invoice-domain.js';
import {invoicePaper} from './invoice-paper.js';
export function createInvoiceEditor(ctx){
 const {getState:S,open,dialog,btn,esc,icon,save,render,toast,detail}=ctx;
 let draft=null,design=null,mode='',uploadGeneration=0;
 const field=(label,name,value,attrs='')=>`<label class="field">${label}<input name="${name}" value="${esc(value)}" ${attrs}></label>`;
 const error='<div class="form-error" role="alert"></div>';
 const sample=()=>({business:S().settings.business,number:'INV-001',issued:today(),due:today(),clientName:'Juniper Studio',clientEmail:'hello@juniper.example',items:[{description:'Brand strategy',quantity:1,rate:150000,amount:150000},{description:'Design consultation',quantity:4,rate:12500,amount:50000}],subtotal:200000,amount:200000,paid:0,paymentInstructions:S().settings.paymentInstructions||'Bank transfer · Include the invoice number as your reference.',design});
 function capture(){if(mode!=='invoice')return;const f=dialog.querySelector('#create-invoice-form');if(!f)return;const v=Object.fromEntries(new FormData(f));Object.assign(draft,{...v,items:[...f.querySelectorAll('.invoice-item-edit')].map(row=>({description:row.querySelector('[data-item=description]').value,quantity:row.querySelector('[data-item=quantity]').value,rate:Math.round(Number(row.querySelector('[data-item=rate]').value)*100)})),design});}
 function currentPreview(){try{return prepareInvoice(S(),{...draft,design});}catch{const c=S().clients.find(c=>c.id===draft?.clientId);let totals;try{totals=calculateInvoice(draft.items,draft.taxRate);}catch{totals={items:[],subtotal:0,amount:0};}return {...sample(),...draft,number:'Draft',...totals,clientName:c?.name||'Client name',clientEmail:c?.email||'',design};}}
 function refresh(){const el=dialog.querySelector('#invoice-live-preview');if(el)el.innerHTML=invoicePaper(mode==='invoice'?currentPreview():sample());const total=dialog.querySelector('#invoice-editor-total');if(total){try{total.textContent=money(calculateInvoice(draft.items,draft.taxRate).amount);}catch{total.textContent='Check line items';}}}
 function cards(){return `<div class="invoice-template-grid" aria-label="Invoice templates">${invoiceTemplates.map(t=>`<button type="button" class="template-card ${design.template===t.id?'selected':''}" data-action="choose-invoice-template" data-template="${t.id}" aria-pressed="${design.template===t.id}" aria-label="${t.name} template"><span class="template-mini mini-${t.id}" style="--invoice-accent:${design.color}" aria-hidden="true"><i class="mini-brand"></i><i class="mini-title"></i><i class="mini-rule"></i><i class="mini-lines"></i><i class="mini-total"></i></span><strong>${t.name}</strong><small>${t.description}</small></button>`).join('')}</div>`;}
 function branding(){return `<section class="invoice-brand-controls"><h3>Branding</h3><div class="logo-control">${design.logo?`<img src="${design.logo}" alt="Your logo preview">`:`<span class="logo-placeholder">${icon('documents')}</span>`}<div><label class="field">Business logo<input type="file" name="logoFile" accept="image/png,image/jpeg,image/webp"></label><small>PNG, JPEG, or WebP · up to 2 MB</small>${design.logo?btn('Remove logo','remove-invoice-logo','','subtle'):''}</div></div><div class="field-row"><label class="field">Accent color<input type="color" name="brandColor" value="${design.color}"></label>${field('Hex color','brandHex',design.color,'maxlength="7" pattern="#[0-9a-fA-F]{6}"')}</div><label class="field">Business details<textarea name="issuerDetails" rows="3" maxlength="1000" placeholder="Business address, email, tax ID…">${esc(design.issuerDetails)}</textarea></label><label class="field">Footer<textarea name="footer" rows="2" maxlength="500">${esc(design.footer)}</textarea></label></section>`;}
 function templates(){mode='templates';uploadGeneration++;design=structuredClone(S().settings.invoiceDesign||defaultInvoiceDesign());open('Invoice templates',`<form id="invoice-template-form"><div class="invoice-workbench"><div class="invoice-editor-controls"><p class="hint">Choose a default for new invoices. Existing invoices keep their design.</p>${cards()}${branding()}${error}</div><div class="invoice-preview-pane"><div class="preview-pane-label">LIVE PREVIEW <span>USD</span></div><div id="invoice-live-preview">${invoicePaper(sample())}</div></div></div><div class="dialog-footer">${btn('Cancel','close')}<button class="btn primary" type="submit">Save default template</button></div></form>`);dialog.classList.add('invoice-workbench-dialog');}
 function start(){mode='invoice';uploadGeneration++;design=structuredClone(S().settings.invoiceDesign||defaultInvoiceDesign());draft={key:uid(),clientId:S().clients.find(c=>!c.archived)?.id||'',projectId:'',issued:today(),due:new Date(Date.now()+14*86400000).toISOString().slice(0,10),billingAddress:'',notes:'',paymentInstructions:S().settings.paymentInstructions||'',items:[{description:'',quantity:1,rate:0}],taxRate:0,design};editor();}
 function editor(){const clients=S().clients.filter(c=>!c.archived),projects=S().projects.filter(p=>!p.archived&&p.status!=='cancelled'&&p.clientId===draft.clientId);open('New invoice',`<form id="create-invoice-form"><div class="invoice-workbench"><div class="invoice-editor-controls"><div class="editor-section-heading"><h3>Invoice details</h3><span class="badge">USD</span></div><div class="field-row"><label class="field">Client<select name="clientId" required><option value="">Choose a client</option>${clients.map(c=>`<option value="${c.id}" ${c.id===draft.clientId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label class="field">Project (optional)<select name="projectId"><option value="">No project</option>${projects.map(p=>`<option value="${p.id}" ${p.id===draft.projectId?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label></div><p class="hint">One-off invoices are separate from a project's agreed milestone schedule.</p><div class="field-row">${field('Issue date','issued',draft.issued,'type="date" required')}${field('Due date','due',draft.due,'type="date" required')}</div><label class="field">Client billing address (optional)<textarea name="billingAddress" rows="2" maxlength="1000">${esc(draft.billingAddress)}</textarea></label><section class="invoice-items-editor"><h3>Line items</h3>${draft.items.map((l,n)=>`<div class="invoice-item-edit"><label class="field item-description">Description<input data-item="description" aria-label="Item ${n+1} description" value="${esc(l.description)}" maxlength="300" required placeholder="e.g. Design consultation"></label><label class="field">Qty<input data-item="quantity" aria-label="Item ${n+1} quantity" type="number" value="${l.quantity}" min="0.01" step="0.01" max="100000" required></label><label class="field">Rate (USD)<input data-item="rate" aria-label="Item ${n+1} rate" type="number" value="${l.rate/100}" min="0" step="0.01" max="1000000" required></label><button type="button" class="icon-btn" data-action="remove-invoice-item" data-index="${n}" aria-label="Remove item ${n+1}" ${draft.items.length===1?'disabled':''}>${icon('close')}</button></div>`).join('')}${btn(icon('plus')+'Add line item','add-invoice-item','','subtle')}</section><div class="field-row">${field('Tax (%)','taxRate',draft.taxRate,'type="number" min="0" max="100" step="0.01"')}<div class="invoice-edit-total"><small>Total</small><strong id="invoice-editor-total"></strong></div></div><label class="field">Payment instructions<textarea name="paymentInstructions" rows="3" maxlength="3000" placeholder="Bank details and payment reference instructions…">${esc(draft.paymentInstructions)}</textarea></label><label class="field">Notes (optional)<textarea name="notes" rows="2" maxlength="2000">${esc(draft.notes)}</textarea></label><details class="invoice-design-options"><summary>Template & branding <span>${esc(invoiceTemplates.find(t=>t.id===design.template).name)}</span></summary>${cards()}${branding()}</details><p class="hint">Creating an invoice saves its amounts and design. No email is sent or payment collected.</p>${error}</div><div class="invoice-preview-pane"><div class="preview-pane-label">LIVE PREVIEW <span>Number assigned on creation</span></div><div id="invoice-live-preview"></div></div></div><div class="dialog-footer">${btn('Cancel','close')}<button type="submit" class="btn primary" ${!clients.length?'disabled':''}>Create invoice</button></div></form>`);dialog.classList.add('invoice-workbench-dialog');refresh();}
 function updateCards(){dialog.querySelectorAll('[data-action="choose-invoice-template"]').forEach(b=>{const selected=b.dataset.template===design.template;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',selected);});const label=dialog.querySelector('.invoice-design-options summary span');if(label)label.textContent=invoiceTemplates.find(t=>t.id===design.template).name;}
 function handleClick(a,el){if(a==='new-invoice')start();else if(a==='invoice-templates')templates();else if(a==='choose-invoice-template'){capture();design.template=el.dataset.template;updateCards();refresh();}else if(a==='add-invoice-item'){capture();if(draft.items.length>=30)throw Error('Use up to 30 line items.');draft.items.push({description:'',quantity:1,rate:0});editor();}else if(a==='remove-invoice-item'){capture();if(draft.items.length>1)draft.items.splice(Number(el.dataset.index),1);editor();}else if(a==='remove-invoice-logo'){design.logo='';uploadGeneration++;if(mode==='invoice'){capture();editor();dialog.querySelector('details').open=true;}else renderTemplateControls();}else return false;return true;}
 function renderTemplateControls(){dialog.querySelector('.invoice-brand-controls').outerHTML=branding();refresh();}
 function handleInput(el){if(!el.closest('#create-invoice-form,#invoice-template-form')||el.type==='file')return false;const n=el.name;if(n==='brandColor'||n==='brandHex'){if(/^#[0-9a-f]{6}$/i.test(el.value)){design.color=el.value;dialog.querySelector(`[name="${n==='brandColor'?'brandHex':'brandColor'}"]`).value=el.value;dialog.querySelectorAll('.template-mini').forEach(x=>x.style.setProperty('--invoice-accent',design.color));}}else if(n==='issuerDetails'||n==='footer')design[n]=el.value;capture();refresh();return true;}
 async function upload(el){const generation=++uploadGeneration,file=el.files?.[0];if(!file)return;const showError=msg=>{const e=dialog.querySelector('.form-error');if(e)e.textContent=msg;else toast(msg);};try{if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2*1024*1024)throw Error('Choose a PNG, JPEG, or WebP logo under 2 MB.');const bitmap=await createImageBitmap(file);const canvas=document.createElement('canvas'),scale=Math.min(1,512/Math.max(bitmap.width,bitmap.height));canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();const logo=canvas.toDataURL('image/webp',0.9);if(logo.length>550000)throw Error('Choose a simpler or smaller logo.');if(generation!==uploadGeneration||!dialog.open)return;design.logo=logo;renderTemplateControls();toast('Logo added to preview. Save to keep it.');}catch(e){showError(e.message||'Could not read that image.');}finally{el.value='';}}
 function handleChange(el){if(!el.closest('#create-invoice-form,#invoice-template-form'))return false;if(el.name==='logoFile'){upload(el);return true;}if(mode==='invoice'&&el.name==='clientId'){capture();draft.projectId='';editor();return true;}return handleInput(el);}
 function handleSubmit(f){if(f.id==='invoice-template-form'){saveInvoiceDefaults(S(),design);save();dialog.close();toast('Default invoice template saved.');}else if(f.id==='create-invoice-form'){capture();const i=createManualInvoice(S(),draft,draft.key);save();render();detail(i.id);toast(`${i.number} created.`);}else return false;return true;}
 return {handleClick,handleInput,handleChange,handleSubmit};
}
